#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, W, H, etc)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "deriche.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Array initialization: replicate the Polybench init_array,
 * but using Halide::Buffer for the arrays.
 *
 * We express the initialization as Halide Funcs and add a
 * cache‑friendly, vectorized schedule; this work is done
 * outside the timed region.
 */
static void init_array(int w,
                       int h,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> imgIn,
                       Halide::Buffer<num_t, 2> imgOut) {
    // Silence unused parameter warnings (sizes are implied by the Buffers).
    (void)w;
    (void)h;

    // Parameter of the filter.
    *alpha = (num_t)0.25;

    // imgIn[i][j] = ((313*i + 991*j) % 65536) / 65535.0f;
    //
    // In C: imgIn has type [W][H] and is accessed as imgIn[i][j].
    // The second index j is the fastest varying. In Halide::Buffer,
    // the first dimension is the fastest varying, so we map:
    //   imgIn(i_c, j_c)  <->  imgIn(j_c, i_c)
    // and allocate Buffer(h, w).
    Var i("i"), j("j");
    Func init_in("init_in"), init_out("init_out");

    Expr val = (313 * i + 991 * j) % 65536;
    init_in(j, i) = cast<num_t>(val) / cast<num_t>(65535.0f);

    // imgOut is not initialized in the original C code, but we'll
    // set it to zero for completeness.
    init_out(j, i) = cast<num_t>(0);

    // ------------------------------------------------------------------
    // Optimized schedule for initialization:
    //  - tile into 2D blocks
    //  - vectorize along the fast (j/x) dimension
    //  - parallelize across tiles in the slower (i/y) dimension
    // Initialization is done once and is not timed, but we keep it
    // efficient to avoid skewing overall benchmarking for many runs.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());
    const int tile_x = vec * 8;  // multiple of vector width
    const int tile_y = 32;

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    init_in
        .compute_root()
        .tile(j, i, xo, yo, xi, yi, tile_x, tile_y, TailStrategy::GuardWithIf)
        .vectorize(xi, vec)
        .parallel(yo);

    init_out
        .compute_root()
        .tile(j, i, xo, yo, xi, yi, tile_x, tile_y, TailStrategy::GuardWithIf)
        .vectorize(xi, vec)
        .parallel(yo);

    // Fill imgIn and imgOut.
    init_in.realize(imgIn);
    init_out.realize(imgOut);
}

int main(int argc, char *argv[]) {
    // Problem size (Polybench constants).
    int w = W;
    int h = H;

    // Allocate arrays as Halide buffers.
    //
    // C layout: imgIn[w][h]   -> indices imgIn[i][j]
    // Halide   : Buffer(h, w) -> indices imgIn(j, i)
    Halide::Buffer<num_t, 2> imgIn(h, w);
    Halide::Buffer<num_t, 2> imgOut(h, w);
    Halide::Buffer<num_t, 2> y1(h, w);
    Halide::Buffer<num_t, 2> y2(h, w);

    // Scalar parameter.
    num_t alpha;

    // Initialize input (not timed).
    init_array(w, h, &alpha, imgIn, imgOut);

    // --------------------------------------------------------------------
    // Halide pipeline for the pointwise combinations:
    //
    // We keep the IIR recurrences (horizontal/vertical passes) as
    // explicit C++ loops over Buffers (Halide cannot express these
    // general recurrences directly without host control), but we
    // express the two purely pointwise "combine" stages as a single
    // Halide Func with an explicit schedule for locality, SIMD, and
    // parallelism.
    // --------------------------------------------------------------------
    Var x("x"), y("y");

    // y1 and y2 will be passed into Halide as ImageParams.
    ImageParam y1_param(type_of<num_t>(), 2, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 2, "y2_param");

    // Scale factor (c1 or c2); kept as a Param so that the same
    // compiled pipeline can be reused for both combinations.
    Param<num_t> scale("scale");

    // Single combination Func:
    //   imgOut = scale * (y1 + y2)
    Func combine("combine");
    combine(x, y) = scale * (y1_param(x, y) + y2_param(x, y));

    // --------------------------------------------------------------------
    // Optimized schedule for combine:
    //  - tile into 2D tiles
    //  - vectorize across the fast (x) dimension (dimension 0: j)
    //  - parallelize across tiles of the slower (y) dimension
    // --------------------------------------------------------------------
    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");
    const int tile_x = vec * 8;  // tile width along fast dimension
    const int tile_y = 32;       // tile height along slow dimension

    combine
        .compute_root()
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y, TailStrategy::GuardWithIf)
        .vectorize(xi, vec)
        .parallel(yo);

    // JIT-compile the combination pipeline ahead of time so we don't
    // measure compilation cost in the timed region.
    combine.compile_jit(target);

    // --------------------------------------------------------------------
    // Compute Deriche filter coefficients on the host (scalar math).
    // This mirrors the Polybench kernel_deriche coefficient setup.
    // --------------------------------------------------------------------
    num_t ea   = std::exp(-alpha);                 // exp(-alpha)
    num_t e2a  = std::exp(num_t(2.0) * alpha);     // exp(2*alpha)
    num_t e_2a = std::exp(num_t(-2.0) * alpha);    // exp(-2*alpha)

    num_t k = (num_t(1.0) - ea) * (num_t(1.0) - ea) /
              (num_t(1.0) + num_t(2.0) * alpha * ea - e2a);

    num_t a1 = k;
    num_t a5 = k;

    num_t a2 = k * ea * (alpha - num_t(1.0));
    num_t a6 = a2;

    num_t a3 = k * ea * (alpha + num_t(1.0));
    num_t a7 = a3;

    num_t a4 = -k * e_2a;
    num_t a8 = a4;

    num_t b1 = std::pow(num_t(2.0), -alpha);
    num_t b2 = -e_2a;

    // Combination coefficients (1.0 in this benchmark, but kept as vars).
    const num_t c1 = (num_t)1;
    const num_t c2 = (num_t)1;

    // --------------------------------------------------------------------
    // Main computational kernel: Deriche filter.
    //
    // Due to the loop-carried dependencies (IIR recurrences) along rows
    // and columns, we implement the recursive passes as explicit C++
    // loops over Halide::Buffer data, and use the Halide Func 'combine'
    // for the purely pointwise passes (the two combinations).
    //
    // Buffer indexing:
    //   original C:   imgIn[i][j]
    //   Halide here:  imgIn(j, i)
    // where i in [0, w) and j in [0, h).
    // Dimension 0 (x/j) is the fast/contiguous dimension.
    // --------------------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // 1) Horizontal forward recursion (along the fast dimension j).
    for (int i = 0; i < w; ++i) {
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);
        num_t xm1 = num_t(0);

        for (int j = 0; j < h; ++j) {
            num_t x_ij = imgIn(j, i);
            num_t y_ij = a1 * x_ij + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1(j, i) = y_ij;

            xm1 = x_ij;
            ym2 = ym1;
            ym1 = y_ij;
        }
    }

    // 2) Horizontal backward recursion (reverse along j).
    for (int i = 0; i < w; ++i) {
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);
        num_t xp1 = num_t(0);
        num_t xp2 = num_t(0);

        for (int j = h - 1; j >= 0; --j) {
            num_t y_ij = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2(j, i) = y_ij;

            xp2 = xp1;
            xp1 = imgIn(j, i);
            yp2 = yp1;
            yp1 = y_ij;
        }
    }

    // 3) First pointwise combination:
    //    imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    y1_param.set(y1);
    y2_param.set(y2);
    scale.set(c1);
    combine.realize(imgOut);

    // 4) Vertical forward recursion (top -> bottom, along i).
    for (int j = 0; j < h; ++j) {
        num_t tm1 = num_t(0);
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);

        for (int i = 0; i < w; ++i) {
            num_t x_ij = imgOut(j, i);
            num_t y_ij = a5 * x_ij + a6 * tm1 + b1 * ym1 + b2 * ym2;
            y1(j, i) = y_ij;

            tm1 = x_ij;
            ym2 = ym1;
            ym1 = y_ij;
        }
    }

    // 5) Vertical backward recursion (bottom -> top, along i).
    for (int j = 0; j < h; ++j) {
        num_t tp1 = num_t(0);
        num_t tp2 = num_t(0);
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);

        for (int i = w - 1; i >= 0; --i) {
            num_t y_ij = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            y2(j, i) = y_ij;

            tp2 = tp1;
            tp1 = imgOut(j, i);
            yp2 = yp1;
            yp1 = y_ij;
        }
    }

    // 6) Final pointwise combination:
    //    imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
    y1_param.set(y1);
    y2_param.set(y2);
    scale.set(c2);
    combine.realize(imgOut);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // --------------------------------------------------------------------
    // Output and timing, similar style to example/gemm.cpp.
    // --------------------------------------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < w; ++i) {
            for (int j = 0; j < h; ++j) {
                // Original C prints imgOut[i][j]; here we map to imgOut(j, i).
                std::cerr << imgOut(j, i) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
