    // imgIn[i][j] = ((313*i + 991*j) % 65536) / 65535.0f;
    // Mapping: C's imgIn[i][j] -> Halide imgIn(j, i)
    Expr val_int = (313 * i + 991 * j) % 65536;
    Expr denom   = cast<num_t>(Expr(65535.0f));

    init_in(j, i) = cast<num_t>(val_int) / denom;

    // imgOut is not initialized in the original C code, but we'll
    // set it to zero for completeness.
    init_out(j, i) = cast<num_t>(0);

    // We don't time initialization, so we keep the schedule simple.
    init_in.realize(imgIn);
    init_out.realize(imgOut);
}

