    // Problem size (Polybench constants).
    int w = W;
    int h = H;

    // Allocate arrays as Halide buffers.
    //
    // Original C layout: imgIn[w][h]   -> indices imgIn[i][j],
    // with j (second index) contiguous.
    // Here: Buffer(h, w) and always access as (j, i),
    // so j is still the contiguous dimension.
    Halide::Buffer<num_t, 2> imgIn(h, w);
    Halide::Buffer<num_t, 2> imgOut(h, w);
    Halide::Buffer<num_t, 2> y1(h, w);
    Halide::Buffer<num_t, 2> y2(h, w);

    // Scalar parameter.
    num_t alpha;

    // Initialize input.
    init_array(w, h, &alpha, imgIn, imgOut);

    // --------------------------------------------------------------------
    // Halide pipeline for the two pointwise combination stages:
    //
    //    imgOut = c * (y1 + y2)
    //
    // We use a single Func parameterized by a Halide Param `combine_scale`
    // so that we JIT-compile once and reuse the same pipeline for both
    // combination passes (c1 and c2).
    // --------------------------------------------------------------------
    Var x("x"), y("y");

    // y1 and y2 will be passed into Halide as ImageParams.
    ImageParam y1_param(type_of<num_t>(), 2, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 2, "y2_param");

    // Scalar scale factor for the combination (c1 or c2).
    Param<num_t> combine_scale("combine_scale");

    // Pointwise combination Func.
    Func combine("combine");
    combine(x, y) = combine_scale * (y1_param(x, y) + y2_param(x, y));

    // ---------------- Scheduling for the Halide combination Func ----------------
    //
    // Memory layout: imgOut/y1/y2 have shape (h, w) and are indexed as (x = j, y = i).
    // Dimension 0 (x) is contiguous; dimension 1 (y) is strided.
    //
    // We:
    //   - tile the 2D domain to improve cache locality
    //   - parallelize across tiles in the outer y dimension (rows)
    //   - vectorize across the inner x dimension (columns), which is contiguous
    //
    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    // Simple heuristic: choose a vector width based on element size
    // (8-wide for float, 4-wide for double or larger types).
    const int vec_width = (sizeof(num_t) == 4) ? 8 : 4;
    const int tile_x    = 32;  // tile size along contiguous dimension (x = j)
    const int tile_y    = 32;  // tile size along y (i)

    combine
        .compute_root()
        // Tile the iteration space: x = xo*tile_x + xi, y = yo*tile_y + yi.
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
        // Vectorize across the contiguous inner x coordinates.
        .vectorize(xi, vec_width)
        // Parallelize across tiles in the y dimension.
        .parallel(yo);

    // JIT-compile the combination pipeline in advance so we don't
    // measure compilation time.
    combine.compile_jit();

    // --------------------------------------------------------------------
    // Compute Deriche filter coefficients on the host (scalar math).
    // This mirrors the Polybench kernel_deriche coefficient setup.
    // --------------------------------------------------------------------
    num_t ea   = std::exp(-alpha);                    // exp(-alpha)
    num_t e2a  = std::exp(num_t(2.0) * alpha);        // exp(2*alpha)
    num_t e_2a = std::exp(num_t(-2.0) * alpha);       // exp(-2*alpha)

    num_t k = (num_t(1.0) - ea) * (num_t(1.0) - ea) /
              (num_t(1.0) + num_t(2.0) * alpha * ea - e2a);

    num_t a1 = k;
    num_t a5 = k;

    num_t a2 = k * ea * (alpha - num_t(1.0));
    num_t a6 = a2;

    num_t a3 = k * ea * (alpha + num_t(1.0));
    num_t a7 = a3;

    num_t a4 = -k * e_2a;
    num_t a8 = a4;

    num_t b1 = std::pow(num_t(2.0), -alpha);
    num_t b2 = -e_2a;

    // Combination scales (both equal to 1.0 in this benchmark, but kept general).
    num_t c1 = (num_t)1;
    num_t c2 = (num_t)1;

    // --------------------------------------------------------------------
    // Main computational kernel: Deriche filter.
    //
    // Due to the loop-carried dependencies (IIR recurrences) along rows
    // and columns, we keep the recursive passes as explicit C++ loops
    // over Halide::Buffer data. This follows the recommended pattern
    // for dynamic-programming / IIR-like algorithms in Halide:
    // express the purely pointwise work as Funcs, and drive the
    // recurrent passes from the host.
    //
    // Buffer indexing:
    //   original C:   imgIn[i][j], with i in [0, W), j in [0, H)
    //   here:         imgIn(j, i)
    // where:
    //   i in [0, w) is the "row" (slow dimension),
    //   j in [0, h) is the "column" (fast / contiguous dimension).
    // --------------------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // 1) Horizontal forward recursion (left -> right) along each row.
    //
    // For each fixed i, the recurrence is over j, and rows are independent.
    for (int i = 0; i < w; ++i) {
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);
        num_t xm1 = num_t(0);

        // j traverses the contiguous dimension (first Halide dim).
        for (int j = 0; j < h; ++j) {
            num_t x_ij = imgIn(j, i);
            num_t y_ij = a1 * x_ij + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1(j, i) = y_ij;

            xm1 = x_ij;
            ym2 = ym1;
            ym1 = y_ij;
        }
    }

    // 2) Horizontal backward recursion (right -> left) along each row.
    for (int i = 0; i < w; ++i) {
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);
        num_t xp1 = num_t(0);
        num_t xp2 = num_t(0);

        for (int j = h - 1; j >= 0; --j) {
            num_t y_ij = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2(j, i) = y_ij;

            xp2 = xp1;
            xp1 = imgIn(j, i);
            yp2 = yp1;
            yp1 = y_ij;
        }
    }

    // 3) First pointwise combination:
    //    imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    //
    // Implemented via the Halide Func `combine` with combine_scale = c1.
    y1_param.set(y1);
    y2_param.set(y2);
    combine_scale.set(c1);
    combine.realize(imgOut);

    // 4) Vertical forward recursion (top -> bottom) along each column.
    //
    // For each fixed j, the recurrence is over i; columns are independent.
    for (int j = 0; j < h; ++j) {
        num_t tm1 = num_t(0);
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);

        for (int i = 0; i < w; ++i) {
            num_t x_ij = imgOut(j, i);
            num_t y_ij = a5 * x_ij + a6 * tm1 + b1 * ym1 + b2 * ym2;
            y1(j, i) = y_ij;

            tm1 = x_ij;
            ym2 = ym1;
            ym1 = y_ij;
        }
    }

