    for (int j = 0; j < h; ++j) {
        num_t tp1 = num_t(0);
        num_t tp2 = num_t(0);
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);

        for (int i = w - 1; i >= 0; --i) {
            num_t y_ij = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            y2(j, i) = y_ij;

            tp2 = tp1;
            tp1 = imgOut(j, i);
            yp2 = yp1;
            yp1 = y_ij;
        }
    }

    // 6) Final pointwise combination:
    //    imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
    //
    // Again via the same Halide Func `combine`, now with combine_scale = c2.
    y1_param.set(y1);
    y2_param.set(y2);
    combine_scale.set(c2);
    combine.realize(imgOut);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // --------------------------------------------------------------------
    // Output and timing, similar style to example/gemm.cpp.
    // --------------------------------------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < w; ++i) {
