    // C layout: imgIn[w][h]   -> indices imgIn[i][j]
    // Halide   : Buffer(h, w) -> indices imgIn(j, i)
    // (first dimension j is the contiguous one, matching C's second index)
    Halide::Buffer<num_t, 2> imgIn(h, w);
    Halide::Buffer<num_t, 2> imgOut(h, w);
    Halide::Buffer<num_t, 2> y1(h, w);
    Halide::Buffer<num_t, 2> y2(h, w);

    // Scalar parameter.
    num_t alpha;

    // Initialize input (and zero imgOut).
    init_array(w, h, &alpha, imgIn, imgOut);

    // --------------------------------------------------------------------
    // Halide pipeline: pointwise combinations only.
    //
    // The Deriche filter has 1D IIR recurrences along rows and columns.
    // Those have loop-carried dependencies that cannot be expressed as
    // legal Halide reductions without violating Halide's update rules.
    //
    // We therefore:
    //   * Implement the purely pointwise stages in Halide (for vectorized,
    //     parallel execution).
    //   * Implement the IIR recurrences as explicit C++ loops over Buffers.
    // --------------------------------------------------------------------
    Var x("x"), y("y");

    // y1 and y2 will be passed into Halide as ImageParams.
    // They always share the same layout as imgIn/imgOut (Buffer(h, w)):
    //   x = j (0..h-1, contiguous), y = i (0..w-1).
    ImageParam y1_param(type_of<num_t>(), 2, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 2, "y2_param");

    // Two pointwise combinations:
    //
    // 1) After horizontal passes:
    //      imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    //
    // 2) After vertical passes:
    //      imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
    //
    // In this benchmark both c1 and c2 are 1.0, but we keep them
    // explicit for clarity.
    Func combine1("combine1");
    Func combine2("combine2");

    const num_t c1 = (num_t)1;
    const num_t c2 = (num_t)1;

    combine1(x, y) = c1 * (y1_param(x, y) + y2_param(x, y));
    combine2(x, y) = c2 * (y1_param(x, y) + y2_param(x, y));

    // --------------------------------------------------------------------
    // Schedule for the Halide pointwise stages.
    //
    // Buffers are (h, w): x = j (height, contiguous), y = i (width).
    // We:
    //   * Traverse row-major with x innermost.
    //   * Vectorize across x (contiguous) using the natural SIMD width.
    //   * Parallelize across y (independent scanlines).
    // --------------------------------------------------------------------
    Target target = get_host_target();
    const int vec = natural_vector_size<num_t>(target);

    combine1
        .compute_root()
        .reorder(x, y)      // x = j inner (contiguous), y = i outer
        .vectorize(x, vec)  // SIMD across columns
        .parallel(y);       // parallel across rows

    combine2
        .compute_root()
        .reorder(x, y)
        .vectorize(x, vec)
        .parallel(y);

    // JIT-compile the small Halide pipelines in advance so we don't
    // measure compilation time.
    combine1.compile_jit(target);
    combine2.compile_jit(target);

    // --------------------------------------------------------------------
    // Compute Deriche filter coefficients on the host (scalar math).
    // This mirrors the Polybench kernel_deriche coefficient setup.
    // --------------------------------------------------------------------
    num_t ea   = std::exp(-alpha);                     // exp(-alpha)
    num_t e2a  = std::exp(num_t(2.0) * alpha);         // exp(2*alpha)
    num_t e_2a = std::exp(num_t(-2.0) * alpha);        // exp(-2*alpha)

    num_t k = (num_t(1.0) - ea) * (num_t(1.0) - ea) /
              (num_t(1.0) + num_t(2.0) * alpha * ea - e2a);

    num_t a1 = k;
    num_t a5 = k;

    num_t a2 = k * ea * (alpha - num_t(1.0));
    num_t a6 = a2;

    num_t a3 = k * ea * (alpha + num_t(1.0));
    num_t a7 = a3;

    num_t a4 = -k * e_2a;
    num_t a8 = a4;

    num_t b1 = std::pow(num_t(2.0), -alpha);
    num_t b2 = -e_2a;

    // --------------------------------------------------------------------
    // Main computational kernel: Deriche filter.
    //
    // Due to the loop-carried dependencies (IIR recurrences) along rows
    // and columns, we keep the recurrences as explicit C++ loops over
    // Halide::Buffer data, and use Halide Funcs for the two purely
    // pointwise combination passes (combine1 and combine2).
    //
    // Buffer indexing:
    //   original C:   imgIn[i][j]
    //   Halide here:  imgIn(j, i)
    //   where i in [0, w) and j in [0, h).
    //
    // The loops are structured to keep the recurrence direction
    // sequential while accessing along the contiguous dimension
    // whenever possible for better cache/SIMD behavior.
    // --------------------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // 1) Horizontal forward recursion (left -> right).
    //
    // For each row i, we step along j (contiguous in memory for Buffer(h,w)):
    //   y1[i,j] = a1*x[i,j] + a2*x[i,j-1] + b1*y1[i,j-1] + b2*y1[i,j-2]
    // with zero initial conditions.
    for (int i = 0; i < w; ++i) {
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);
        num_t xm1 = num_t(0);

        for (int j = 0; j < h; ++j) {
            num_t x_ij = imgIn(j, i);
            num_t y_ij = a1 * x_ij + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1(j, i) = y_ij;

            xm1 = x_ij;
            ym2 = ym1;
            ym1 = y_ij;
        }
    }

    // 2) Horizontal backward recursion (right -> left).
    //
    // For each row i, we traverse j from h-1 down to 0:
    //   y2[i,j] = a3*x[i,j+1] + a4*x[i,j+2] + b1*y2[i,j+1] + b2*y2[i,j+2]
    // with x[i,h]=x[i,h+1]=0 and y2[i,h]=y2[i,h+1]=0.
    for (int i = 0; i < w; ++i) {
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);
        num_t xp1 = num_t(0);
        num_t xp2 = num_t(0);

        for (int j = h - 1; j >= 0; --j) {
            num_t y_ij = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2(j, i) = y_ij;

            xp2 = xp1;
            xp1 = imgIn(j, i);
            yp2 = yp1;
            yp1 = y_ij;
        }
    }

    // 3) First pointwise combination:
    //    imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    //
    // This is a pure elementwise map, scheduled above as
    // vectorized across x (contiguous) and parallel across y.
    y1_param.set(y1);
    y2_param.set(y2);
    combine1.realize(imgOut);

    // 4) Vertical forward recursion (top -> bottom).
    //
    // For each column j, we now treat imgOut as input and perform:
    //   y1[i,j] = a5*x[i,j] + a6*x[i-1,j] + b1*y1[i-1,j] + b2*y1[i-2,j]
    // with zero initial conditions.
    //
    // Note: These loops walk along the non-contiguous dimension of
    // Buffer(h,w). This is inherent in the algorithm (column-wise
    // IIR), but we keep the stride-1 dimension as the inner loop
    // wherever possible in the rest of the code.
    for (int j = 0; j < h; ++j) {
        num_t tm1 = num_t(0);
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);

        for (int i = 0; i < w; ++i) {
            num_t x_ij = imgOut(j, i);
            num_t y_ij = a5 * x_ij + a6 * tm1 + b1 * ym1 + b2 * ym2;
            y1(j, i) = y_ij;

            tm1 = x_ij;
            ym2 = ym1;
            ym1 = y_ij;
        }
    }

    // 5) Vertical backward recursion (bottom -> top).
    //
    // For each column j, we traverse i from w-1 down to 0:
    //   y2[i,j] = a7*x[i+1,j] + a8*x[i+2,j] + b1*y2[i+1,j] + b2*y2[i+2,j]
    // with x[w,j]=x[w+1,j]=0 and y2[w,j]=y2[w+1,j]=0.
    for (int j = 0; j < h; ++j) {
        num_t tp1 = num_t(0);
        num_t tp2 = num_t(0);
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);

        for (int i = w - 1; i >= 0; --i) {
            num_t y_ij = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            y2(j, i) = y_ij;

            tp2 = tp1;
            tp1 = imgOut(j, i);
            yp2 = yp1;
            yp1 = y_ij;
        }
    }

    // 6) Final pointwise combination:
    //    imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
    y1_param.set(y1);
    y2_param.set(y2);
    combine2.realize(imgOut);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // --------------------------------------------------------------------
    // Output and timing, similar style to example/gemm.cpp.
    // --------------------------------------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < w; ++i) {
            for (int j = 0; j < h; ++j) {
                // Original C prints imgOut[i][j]; here we map to imgOut(j, i).
                std::cerr << imgOut(j, i) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
